#Requires -Version 5.1
<#
.SYNOPSIS
    Claude Code Windows 토스트 알림(Clawd) 설치 스크립트

.DESCRIPTION
    Claude Code의 Notification / Stop hook에 Windows 토스트 알림을 설정한다.
    - Notification: 승인 대기 등 사용자 확인이 필요할 때 (Clawd + 물음표)
    - Stop        : 작업이 완료됐을 때 (Clawd 만세 + 체크)

    토스트는 사용자가 닫을 때까지 화면에 유지된다(scenario="reminder").
    제목에 프로젝트 폴더 이름을 붙이고, 클릭하면 해당 VS Code 창을 앞으로 가져온다
    (clawd-focus:// 프로토콜을 HKCU에 등록).

.PARAMETER Uninstall
    설치한 hook 설정과 파일을 제거한다.

.PARAMETER Force
    기존 Notification/Stop hook이 있어도 확인 없이 덮어쓴다.

.PARAMETER Language
    표시 언어 (ko / en). 설치 메시지, 알림 문구·버튼, 설정 창에 적용된다.
    생략하면 기존 설정을 유지하고, 처음 설치라면 Windows 표시 언어를 따른다.

.EXAMPLE
    powershell -ExecutionPolicy Bypass -File Install-ClawdNotify.ps1
    powershell -ExecutionPolicy Bypass -File Install-ClawdNotify.ps1 -Language en
    powershell -ExecutionPolicy Bypass -File Install-ClawdNotify.ps1 -Uninstall
#>
[CmdletBinding()]
param(
    [switch]$Uninstall,
    [switch]$Force,
    [ValidateSet('ko', 'en')]
    [string]$Language
)

$ErrorActionPreference = 'Stop'

