# ---------------------------------------------------------------- 경로/상수
$ClaudeDir   = Join-Path $env:USERPROFILE '.claude'
$AssetsDir   = Join-Path $ClaudeDir 'assets'
$SettingsPath= Join-Path $ClaudeDir 'settings.json'
$NotifyScript= Join-Path $ClaudeDir 'claude-notify.ps1'
$SettingsUI  = Join-Path $ClaudeDir 'claude-notify-settings.ps1'
$FocusExe    = Join-Path $ClaudeDir 'claude-notify-focus.exe'
# 이전 버전에서 쓰던 PowerShell 포커스 스크립트 (제거 대상)
$FocusScript = Join-Path $ClaudeDir 'claude-notify-focus.ps1'
$ProtocolKey = 'HKCU:\Software\Classes\clawd-focus'
$AskImage    = Join-Path $AssetsDir 'clawd-ask-hero.png'
$DoneImage   = Join-Path $AssetsDir 'clawd-done-hero.png'
$AskIcon     = Join-Path $AssetsDir 'clawd_question.png'
$DoneIcon    = Join-Path $AssetsDir 'clawd_done.png'
# 알림 헤더와 알림 설정 목록에 쓰는 배지 없는 Clawd 아이콘
$AppIcon     = Join-Path $AssetsDir 'clawd.png'

# 토스트 발신자 ID(AppUserModelId). 토스트 상단 헤더와 알림 설정 목록에 표시될 이름과 아이콘은
# 설치 시 레지스트리에 등록한다. 등록되지 않은 ID로 보내면 Windows가 토스트를 조용히 버린다.
$AppId          = 'ClawdNotify'
$AppDisplayName = 'Clawd Notify'
$AppIdKey       = "HKCU:\Software\Classes\AppUserModelId\$AppId"
# 알림을 처음 받을 때 Windows가 만드는 알림 설정 키 (제거 시 함께 정리)
$AppNotifyKey   = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Notifications\Settings\$AppId"

# ---------------------------------------------------------------- 언어
# 알림 스크립트와 설정 창이 함께 읽는 설정 파일
$ConfigPath  = Join-Path $ClaudeDir 'claude-notify-config.json'

# -Language > 기존 설정 > Windows 표시 언어 순으로 정한다
if (-not $Language) {
    try { $Language = (Get-Content $ConfigPath -Raw -Encoding UTF8 | ConvertFrom-Json).language } catch { }
}
if ($Language -notin 'ko', 'en') {
    $Language = if ([System.Globalization.CultureInfo]::CurrentUICulture.TwoLetterISOLanguageName -eq 'ko') { 'ko' } else { 'en' }
}

# 한국어/영어 문자열 중 현재 언어에 맞는 것을 고른다
function T {
    param([string]$Ko, [string]$En)
    if ($script:Language -eq 'en') { $En } else { $Ko }
}

# ---------------------------------------------------------------- 출력 헬퍼
function Write-Step { param([string]$M) Write-Host "  $M" -ForegroundColor Gray }
function Write-Ok   { param([string]$M) Write-Host "  [OK] $M" -ForegroundColor Green }
function Write-Warn2{ param([string]$M) Write-Host "  [!]  $M" -ForegroundColor Yellow }
function Write-Err2 { param([string]$M) Write-Host "  [X]  $M" -ForegroundColor Red }
function Write-Head { param([string]$M) Write-Host ""; Write-Host $M -ForegroundColor Cyan }

# UTF-8 BOM으로 저장한다.
# BOM이 없으면 PowerShell 5.1이 시스템 ANSI 코드페이지로 읽어 한글이 깨진다.
function Save-Utf8Bom {
    param([string]$Path, [string]$Content)
    [System.IO.File]::WriteAllText($Path, $Content, [System.Text.UTF8Encoding]::new($true))
}

function New-Backup {
    param([string]$Path)
    if (-not (Test-Path $Path)) { return $null }
    $stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
    $bak = "$Path.$stamp.bak"
    Copy-Item $Path $bak -Force
    return $bak
}

# ---------------------------------------------------------------- 알림 스크립트
$NotifyScriptBody = @'
param(
    [string]$Message = "",
    [string]$Title = "Claude Code",
    # reminder = 사용자가 닫을 때까지 유지, default = 몇 초 후 자동으로 사라짐
    [ValidateSet("reminder", "default")]
    [string]$Scenario = "reminder",
    [string]$Logo = "",
    [switch]$LogoCircle,
    [string]$Hero = "",
    [string]$Image = "",
    # Windows 내장 알림음. Silent는 무음.
    [ValidateSet("Default","IM","Mail","Reminder","SMS","Silent",
                 "Alarm","Alarm2","Alarm3","Call","Call2","Call3")]
    [string]$Sound = "Default",
    # 알림음을 반복 재생한다. Alarm/Call 계열에서만 의미가 있다.
    [switch]$LoopSound
)

Add-Type -AssemblyName System.Runtime.WindowsRuntime

# 표시 언어: 설치 스크립트와 설정 창이 쓰는 claude-notify-config.json을 따른다.
# 없으면 Windows 표시 언어를 따른다.
$Lang = $null
try {
    $Lang = (Get-Content (Join-Path $PSScriptRoot "claude-notify-config.json") -Raw -Encoding UTF8 | ConvertFrom-Json).language
} catch { }
if ($Lang -notin "ko", "en") {
    $Lang = if ([System.Globalization.CultureInfo]::CurrentUICulture.TwoLetterISOLanguageName -eq "ko") { "ko" } else { "en" }
}

# 기본 알림 문구는 언어를 바꾸면 hook 설정을 다시 저장하지 않아도 따라 바뀌도록 여기서 번역한다.
# 사용자가 직접 쓴 문구는 그대로 둔다.
$DefaultMessages = @(
    @{ ko = "확인이 필요합니다.";     en = "Claude needs your attention." }
    @{ ko = "작업이 완료되었습니다."; en = "Task completed." }
    @{ ko = "설치가 완료되었습니다."; en = "Installation complete." }
)
if (-not $Message) { $Message = $DefaultMessages[0][$Lang] }
foreach ($m in $DefaultMessages) {
    if ($Message -eq $m.ko -or $Message -eq $m.en) { $Message = $m[$Lang]; break }
}
$LabelSettings = if ($Lang -eq "en") { "Settings" } else { "설정" }
$LabelClose    = if ($Lang -eq "en") { "Close" } else { "닫기" }

# 어느 프로젝트(VS Code 창)에서 온 알림인지 알아낸다.
# hook 실행 시 Claude Code가 CLAUDE_PROJECT_DIR을 넘겨주고, stdin으로도 cwd가 담긴 JSON을 준다.
$ProjectDir = $env:CLAUDE_PROJECT_DIR
if (-not $ProjectDir -and [Console]::IsInputRedirected) {
    try {
        [Console]::InputEncoding = [System.Text.UTF8Encoding]::new($false)
        # stdin이 닫히지 않는 경우(설정 창의 테스트 실행 등)에 멈추지 않도록 시간 제한을 둔다
        $task = [Console]::In.ReadToEndAsync()
        if ($task.Wait(1000) -and $task.Result) {
            $ProjectDir = ($task.Result | ConvertFrom-Json).cwd
        }
    } catch { }
}
$ProjectName = if ($ProjectDir) { Split-Path $ProjectDir -Leaf } else { "" }
if ($ProjectName) { $Title = "$Title · $ProjectName" }

# VS Code 안에서 실행된 경우, 알림을 클릭하면 해당 VS Code 창을 앞으로 가져온다.
# clawd-focus 프로토콜은 설치 시 등록되며 claude-notify-focus.exe가 처리한다.
$launchAttrs = ""
$settingsActionXml = ""
$hasProtocol = Test-Path "Registry::HKEY_CURRENT_USER\Software\Classes\clawd-focus"
$inEditor = ($env:CLAUDE_CODE_ENTRYPOINT -eq "claude-vscode") -or ($env:TERM_PROGRAM -eq "vscode")
if ($ProjectDir -and $inEditor -and $hasProtocol) {
    $uri = "clawd-focus://focus/?path=" + [Uri]::EscapeDataString($ProjectDir)
    $launchAttrs = ' activationType="protocol" launch="' + [System.Security.SecurityElement]::Escape($uri) + '"'
}
# 알림에서 바로 설정 창(settings.bat과 같은 화면)을 여는 버튼
if ($hasProtocol) {
    $settingsActionXml = "<action content=`"$LabelSettings`" arguments=`"clawd-focus://settings`" activationType=`"protocol`" />"
}

$XmlDocument = [Windows.Data.Xml.Dom.XmlDocument, Windows.Data.Xml.Dom, ContentType = WindowsRuntime]
$xml = [Activator]::CreateInstance($XmlDocument)

# XML 특수문자(&, <, > 등)가 그대로 들어가면 LoadXml이 실패하므로 이스케이프한다
$SafeTitle = [System.Security.SecurityElement]::Escape($Title)
$SafeMessage = [System.Security.SecurityElement]::Escape($Message)

# 이미지는 반드시 존재하는 절대 경로여야 한다. 없는 경로를 넘기면
# Windows가 알림 전체를 조용히 버리므로 여기서 걸러낸다.
function Get-ImageElement {
    param([string]$Path, [string]$Placement, [string]$Crop)
    if ([string]::IsNullOrWhiteSpace($Path)) { return "" }
    $resolved = try { (Resolve-Path -LiteralPath $Path -ErrorAction Stop).Path } catch { $null }
    if (-not $resolved) {
        Write-Warning "이미지를 찾을 수 없어 건너뜁니다: $Path"
        return ""
    }
    $src = [System.Security.SecurityElement]::Escape($resolved)
    $attrs = "src=`"$src`""
    if ($Placement) { $attrs += " placement=`"$Placement`"" }
    if ($Crop) { $attrs += " hint-crop=`"$Crop`"" }
    return "<image $attrs />"
}

$logoXml  = Get-ImageElement -Path $Logo -Placement "appLogoOverride" -Crop $(if ($LogoCircle) { "circle" } else { "" })
$heroXml  = Get-ImageElement -Path $Hero -Placement "hero"
$imageXml = Get-ImageElement -Path $Image

# 알림음: Silent는 무음 속성, 나머지는 ms-winsoundevent URI를 쓴다
if ($Sound -eq "Silent") {
    $audioXml = '<audio silent="true" />'
} else {
    $soundMap = @{
        "Default"  = "Notification.Default"
        "IM"       = "Notification.IM"
        "Mail"     = "Notification.Mail"
        "Reminder" = "Notification.Reminder"
        "SMS"      = "Notification.SMS"
        "Alarm"    = "Notification.Looping.Alarm"
        "Alarm2"   = "Notification.Looping.Alarm2"
        "Alarm3"   = "Notification.Looping.Alarm3"
        "Call"     = "Notification.Looping.Call"
        "Call2"    = "Notification.Looping.Call2"
        "Call3"    = "Notification.Looping.Call3"
    }
    $src = "ms-winsoundevent:" + $soundMap[$Sound]
    $loop = if ($LoopSound) { ' loop="true"' } else { '' }
    $audioXml = "<audio src=`"$src`"$loop />"
}

# scenario="reminder"는 알림을 화면에 고정시킨다. Windows는 이 시나리오에
# 최소 하나의 동작을 요구하므로 닫기 버튼을 함께 정의한다.
$xml.LoadXml(@"
<toast scenario="$Scenario"$launchAttrs>
    <visual>
        <binding template="ToastGeneric">
            <text>$SafeTitle</text>
            <text>$SafeMessage</text>
            $logoXml
            $heroXml
            $imageXml
        </binding>
    </visual>
    $audioXml
    <actions>
        $settingsActionXml
        <action content="$LabelClose" arguments="dismiss" activationType="system" />
    </actions>
</toast>
"@)

$ToastNotification = [Windows.UI.Notifications.ToastNotification, Windows.UI.Notifications, ContentType = WindowsRuntime]
$toast = [Activator]::CreateInstance($ToastNotification, $xml)
$ToastManager = [Windows.UI.Notifications.ToastNotificationManager, Windows.UI.Notifications, ContentType = WindowsRuntime]
$notifier = $ToastManager::CreateToastNotifier("__APPID__")
$notifier.Show($toast)
'@

# ---------------------------------------------------------------- 창 포커스 프로그램
# 알림 클릭 시 clawd-focus://focus/?path=<프로젝트 경로> 로 실행된다.
# VS Code는 창이 여러 개여도 프로세스가 하나라서 창 제목의 폴더 이름으로 찾는다.
# powershell.exe는 콘솔 프로그램이라 실행 순간 콘솔 창이 깜빡이므로,
# 설치 시 콘솔 없는 Windows 프로그램(exe)으로 컴파일해서 쓴다.
$FocusSource = @'
using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Runtime.InteropServices;

public static class ClawdFocus {
    delegate bool EnumProc(IntPtr h, IntPtr l);
    [DllImport("user32.dll")] static extern bool EnumWindows(EnumProc f, IntPtr l);
    [DllImport("user32.dll")] static extern bool IsWindowVisible(IntPtr h);
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern int GetWindowText(IntPtr h, StringBuilder s, int n);
    [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
    [DllImport("user32.dll")] static extern bool IsIconic(IntPtr h);
    [DllImport("user32.dll")] static extern bool ShowWindow(IntPtr h, int cmd);
    [DllImport("user32.dll")] static extern bool SetForegroundWindow(IntPtr h);
    [DllImport("user32.dll")] static extern void keybd_event(byte vk, byte scan, uint flags, UIntPtr extra);

    public static void Main(string[] args) {
        if (args.Length == 0) return;
        if (args[0].StartsWith("clawd-focus://settings", StringComparison.OrdinalIgnoreCase)) {
            OpenSettings();
            return;
        }
        Match q =Regex.Match(args[0], "[?&]path=([^&]*)");
        if (!q.Success) return;
        string dir = Uri.UnescapeDataString(q.Groups[1].Value).TrimEnd(Path.DirectorySeparatorChar);
        if (dir.Length == 0) return;
        string name = Path.GetFileName(dir);

        uint[] pids = new[] { "Code", "Code - Insiders", "Cursor" }
            .SelectMany(n => Process.GetProcessesByName(n))
            .Select(p => (uint)p.Id).ToArray();

        // 기본 창 제목: "<편집 중인 파일> - <폴더 이름> - Visual Studio Code"
        // 원격 연결이면 폴더 이름 뒤에 "[WSL: Ubuntu]" 같은 표시가 붙는다.
        Regex title = new Regex(@"(^|\s-\s)" + Regex.Escape(name) + @"(\s\[[^\]]*\])?(\s-\s|$)");
        IntPtr target = IntPtr.Zero;
        if (pids.Length > 0) {
            EnumWindows(delegate (IntPtr h, IntPtr l) {
                if (!IsWindowVisible(h)) return true;
                uint pid; GetWindowThreadProcessId(h, out pid);
                if (Array.IndexOf(pids, pid) < 0) return true;
                StringBuilder sb = new StringBuilder(1024);
                GetWindowText(h, sb, sb.Capacity);
                if (!title.IsMatch(sb.ToString())) return true;
                target = h;
                return false;
            }, IntPtr.Zero);
        }

        if (target != IntPtr.Zero) {
            if (IsIconic(target)) ShowWindow(target, 9);  // SW_RESTORE
            // Windows는 다른 앱이 포커스를 가져가는 것을 막는다. Alt 키 입력을 흉내 내면 허용된다.
            keybd_event(0x12, 0, 0, UIntPtr.Zero);
            keybd_event(0x12, 0, 2, UIntPtr.Zero);
            SetForegroundWindow(target);
        } else if (Directory.Exists(dir)) {
            // 창이 닫혔으면 해당 폴더를 VS Code로 다시 연다
            string[] parts = dir.Split(Path.DirectorySeparatorChar);
            string url = parts[0] + "/" + string.Join("/", parts.Skip(1).Select(Uri.EscapeDataString));
            Process.Start("vscode://file/" + url);
        }
    }

    // 알림의 "설정" 버튼: settings.bat과 같은 설정 창을 연다.
    // CreateNoWindow로 실행해야 PowerShell 콘솔 창이 깜빡이지 않는다.
    static void OpenSettings() {
        string ui = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "claude-notify-settings.ps1");
        if (!File.Exists(ui)) return;
        ProcessStartInfo psi = new ProcessStartInfo("powershell.exe",
            "-NoProfile -ExecutionPolicy Bypass -File \"" + ui + "\"");
        psi.UseShellExecute = false;
        psi.CreateNoWindow = true;
        Process.Start(psi);
    }
}
'@

# ---------------------------------------------------------------- 제거
function Invoke-Uninstall {
    Write-Head (T '=== Clawd 알림 제거 ===' '=== Uninstall Clawd notifications ===')

    if (Test-Path $SettingsPath) {
        $bak = New-Backup $SettingsPath
        Write-Ok ((T '설정 백업: ' 'Settings backup: ') + (Split-Path $bak -Leaf))
        try {
            $json = Get-Content $SettingsPath -Raw -Encoding UTF8 | ConvertFrom-Json
            $removed = @()
            if ($json.PSObject.Properties['hooks']) {
                foreach ($ev in @('Notification','Stop','PermissionRequest')) {
                    if ($json.hooks.PSObject.Properties[$ev]) {
                        # 이 설치 스크립트가 만든 hook만 제거한다
                        $ours = $json.hooks.$ev | Where-Object {
                            $_.hooks | Where-Object { $_.command -like '*claude-notify.ps1*' }
                        }
                        if ($ours) {
                            $json.hooks.PSObject.Properties.Remove($ev)
                            $removed += $ev
                        }
                    }
                }
                if ($json.hooks.PSObject.Properties.Count -eq 0) {
                    $json.PSObject.Properties.Remove('hooks')
                }
            }
            $out = $json | ConvertTo-Json -Depth 20
            Save-Utf8Bom -Path $SettingsPath -Content $out
            # Claude Code는 BOM 없는 JSON을 기대하므로 BOM을 제거한다
            $txt = [System.IO.File]::ReadAllText($SettingsPath, [System.Text.UTF8Encoding]::new($true))
            [System.IO.File]::WriteAllText($SettingsPath, $txt, [System.Text.UTF8Encoding]::new($false))

            if ($removed.Count -gt 0) { Write-Ok ((T 'hook 제거: ' 'Removed hooks: ') + ($removed -join ', ')) }
            else { Write-Warn2 (T '제거할 hook이 없습니다.' 'No hooks to remove.') }
        } catch {
            Write-Err2 ((T '설정 수정 실패: ' 'Failed to update settings: ') + $_.Exception.Message)
            return 1
        }
    } else {
        Write-Warn2 (T 'settings.json이 없습니다.' 'settings.json not found.')
    }

    if (Test-Path $ProtocolKey) {
        Remove-Item $ProtocolKey -Recurse -Force
        Write-Ok (T 'clawd-focus 프로토콜 등록 해제' 'Unregistered clawd-focus protocol')
    }

    # 알림 센터에 남은 알림을 먼저 지운다. 등록을 먼저 해제하면 남은 알림이 정리되지 않는다.
    try {
        Add-Type -AssemblyName System.Runtime.WindowsRuntime -ErrorAction Stop
        $mgr = [Windows.UI.Notifications.ToastNotificationManager, Windows.UI.Notifications, ContentType = WindowsRuntime]
        $mgr::History.Clear($AppId)
    } catch { }
    foreach ($k in @($AppIdKey, $AppNotifyKey)) {
        if (Test-Path $k) { Remove-Item $k -Recurse -Force }
    }
    Write-Ok ((T '알림 발신자 등록 해제: ' 'Unregistered notification sender: ') + $AppDisplayName)

    foreach ($f in @($NotifyScript, $SettingsUI, $FocusExe, $FocusScript, $ConfigPath, $AskImage, $DoneImage, $AskIcon, $DoneIcon, $AppIcon)) {
        if (Test-Path $f) { Remove-Item $f -Force; Write-Ok ((T '삭제: ' 'Deleted: ') + (Split-Path $f -Leaf)) }
    }
    if ((Test-Path $AssetsDir) -and -not (Get-ChildItem $AssetsDir -Force)) {
        Remove-Item $AssetsDir -Force
        Write-Ok (T '빈 assets 폴더 삭제' 'Deleted empty assets folder')
    }

    Write-Host ''
    Write-Host (T '제거 완료. 실행 중인 Claude Code에도 몇 초 안에 반영됩니다.' 'Uninstalled. Running Claude Code sessions pick this up within a few seconds.') -ForegroundColor Green
    return 0
}

# ---------------------------------------------------------------- 설치
function Invoke-Install {
    Write-Host ''
    Write-Host '========================================' -ForegroundColor Cyan
    Write-Host (T '  Claude Code - Clawd 토스트 알림 설치' '  Claude Code - Clawd toast notifications') -ForegroundColor Cyan
    Write-Host '========================================' -ForegroundColor Cyan

    # --- 1. 사전 점검 ---
    Write-Head (T '[1/5] 환경 확인' '[1/5] Checking environment')

    if ([System.Environment]::OSVersion.Version.Major -lt 10) {
        Write-Err2 (T 'Windows 10 이상이 필요합니다(토스트 알림 API).' 'Windows 10 or later is required (toast notification API).')
        return 1
    }
    Write-Ok "Windows $([System.Environment]::OSVersion.Version)"

    # WinRT 토스트 API 사용 가능 여부를 실제로 확인한다
    try {
        Add-Type -AssemblyName System.Runtime.WindowsRuntime -ErrorAction Stop
        $null = [Windows.UI.Notifications.ToastNotificationManager, Windows.UI.Notifications, ContentType = WindowsRuntime]
        Write-Ok (T '토스트 알림 API 사용 가능' 'Toast notification API available')
    } catch {
        Write-Err2 ((T '토스트 API를 사용할 수 없습니다: ' 'Toast API unavailable: ') + $_.Exception.Message)
        return 1
    }

    if (-not (Test-Path $ClaudeDir)) {
        New-Item -ItemType Directory -Path $ClaudeDir -Force | Out-Null
        Write-Ok ((T '생성: ' 'Created: ') + $ClaudeDir)
    } else {
        Write-Ok ((T 'Claude 설정 폴더: ' 'Claude config folder: ') + $ClaudeDir)
    }
    if (-not (Test-Path $AssetsDir)) {
        New-Item -ItemType Directory -Path $AssetsDir -Force | Out-Null
    }

    # 표시 언어 저장 (알림 스크립트와 설정 창이 읽는다)
    $cfg = [PSCustomObject]@{}
    try { $cfg = Get-Content $ConfigPath -Raw -Encoding UTF8 | ConvertFrom-Json } catch { }
    $cfg | Add-Member -NotePropertyName 'language' -NotePropertyValue $Language -Force
    [System.IO.File]::WriteAllText($ConfigPath, ($cfg | ConvertTo-Json), [System.Text.UTF8Encoding]::new($false))
    Write-Ok ((T '표시 언어: ' 'Display language: ') + $(if ($Language -eq 'en') { 'English' } else { '한국어' }))

    # --- 2. 알림 스크립트 ---
    Write-Head (T '[2/5] 알림 스크립트 설치' '[2/5] Installing notification scripts')
    if (Test-Path $NotifyScript) {
        $bak = New-Backup $NotifyScript
        Write-Step ((T '기존 파일 백업: ' 'Backed up existing file: ') + (Split-Path $bak -Leaf))
    }
    # AppId를 실제 값으로 치환한다
    $body = $NotifyScriptBody.Replace('__APPID__', $AppId)
    Save-Utf8Bom -Path $NotifyScript -Content $body
    Write-Ok "claude-notify.ps1 ($([math]::Round((Get-Item $NotifyScript).Length / 1KB, 1)) KB)"

    # 설정 UI
    $uiText = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($Script:B64_UI))
    Save-Utf8Bom -Path $SettingsUI -Content $uiText
    Write-Ok "claude-notify-settings.ps1 ($([math]::Round((Get-Item $SettingsUI).Length / 1KB, 1)) KB)"

    # 알림 클릭 시 VS Code 창을 앞으로 가져오는 프로그램과 clawd-focus:// 프로토콜
    try {
        if (Test-Path $FocusScript) { Remove-Item $FocusScript -Force }
        if (Test-Path $FocusExe) { Remove-Item $FocusExe -Force }
        Add-Type -TypeDefinition $FocusSource -ReferencedAssemblies 'System.Core' `
            -OutputAssembly $FocusExe -OutputType WindowsApplication -ErrorAction Stop
        $cmdKey = Join-Path $ProtocolKey 'shell\open\command'
        New-Item -Path $cmdKey -Force | Out-Null
        Set-ItemProperty -Path $ProtocolKey -Name '(default)' -Value 'URL:Clawd Focus'
        Set-ItemProperty -Path $ProtocolKey -Name 'URL Protocol' -Value ''
        Set-ItemProperty -Path $cmdKey -Name '(default)' -Value ('"{0}" "%1"' -f $FocusExe)
        Write-Ok (T 'claude-notify-focus.exe + clawd-focus 프로토콜 등록 (알림 클릭 시 VS Code 창 전환)' `
                    'claude-notify-focus.exe + clawd-focus protocol (click a toast to switch VS Code windows)')
    } catch {
        Write-Warn2 ((T 'clawd-focus 프로토콜 등록 실패 (알림 클릭 기능만 비활성): ' 'Failed to register clawd-focus protocol (toast click disabled): ') + $_.Exception.Message)
    }

    # --- 3. 이미지 ---
    Write-Head (T '[3/5] Clawd 이미지 설치' '[3/5] Installing Clawd images')
    try {
        [System.IO.File]::WriteAllBytes($AskImage,  [System.Convert]::FromBase64String($Script:B64_ASK))
        [System.IO.File]::WriteAllBytes($DoneImage, [System.Convert]::FromBase64String($Script:B64_DONE))
        Write-Ok "clawd-ask-hero.png  ($([math]::Round((Get-Item $AskImage).Length / 1KB, 1)) KB)"
        Write-Ok "clawd-done-hero.png ($([math]::Round((Get-Item $DoneImage).Length / 1KB, 1)) KB)"
        [System.IO.File]::WriteAllBytes($AskIcon,  [System.Convert]::FromBase64String($Script:B64_ASKICON))
        [System.IO.File]::WriteAllBytes($DoneIcon, [System.Convert]::FromBase64String($Script:B64_DONEICON))
        Write-Ok ('clawd_question.png / clawd_done.png ' + (T '(작은 창용 아이콘 256x256)' '(small icons 256x256)'))
        [System.IO.File]::WriteAllBytes($AppIcon, [System.Convert]::FromBase64String($Script:B64_APPICON))
        Write-Ok ('clawd.png ' + (T '(알림 헤더 아이콘)' '(notification header icon)'))
    } catch {
        Write-Err2 ((T '이미지 생성 실패: ' 'Failed to write images: ') + $_.Exception.Message)
        return 1
    }

    # 토스트 헤더에 "Windows PowerShell" 대신 이 이름과 아이콘이 표시되도록 발신자 ID를 등록한다
    try {
        New-Item -Path $AppIdKey -Force | Out-Null
        Set-ItemProperty -Path $AppIdKey -Name 'DisplayName' -Value $AppDisplayName
        Set-ItemProperty -Path $AppIdKey -Name 'IconUri' -Value $AppIcon
        Write-Ok ((T '알림 발신자 등록: ' 'Registered notification sender: ') + $AppDisplayName)
    } catch {
        Write-Err2 ((T '알림 발신자 등록 실패: ' 'Failed to register notification sender: ') + $_.Exception.Message)
        return 1
    }

    # --- 4. settings.json 병합 ---
    Write-Head (T '[4/5] hook 설정 등록' '[4/5] Registering hooks')

    # 기본 문구는 claude-notify.ps1이 표시 언어에 맞게 번역하므로 어느 언어로 저장해도 된다
    $quoted = '"{0}"' -f $NotifyScript
    $base   = "powershell.exe -NoProfile -ExecutionPolicy Bypass -File $quoted"
    $cmdNotify = '{0} -Message "{1}" -Logo "{2}"' -f $base, (T '확인이 필요합니다.' 'Claude needs your attention.'), $AskIcon
    $cmdStop   = '{0} -Message "{1}" -Logo "{2}"' -f $base, (T '작업이 완료되었습니다.' 'Task completed.'), $DoneIcon
    if (Test-Path $SettingsPath) {
        $bak = New-Backup $SettingsPath
        Write-Step ((T '기존 설정 백업: ' 'Backed up settings: ') + (Split-Path $bak -Leaf))
        try {
            $raw = Get-Content $SettingsPath -Raw -Encoding UTF8
            if ([string]::IsNullOrWhiteSpace($raw)) { $settings = [PSCustomObject]@{} }
            else { $settings = $raw | ConvertFrom-Json }
        } catch {
            Write-Err2 ((T 'settings.json을 읽을 수 없습니다: ' 'Cannot read settings.json: ') + $_.Exception.Message)
            Write-Warn2 ((T '백업본: ' 'Backup: ') + $bak)
            return 1
        }
    } else {
        $settings = [PSCustomObject]@{}
        Write-Step (T 'settings.json을 새로 만듭니다.' 'Creating settings.json.')
    }

    if (-not $settings.PSObject.Properties['hooks']) {
        $settings | Add-Member -NotePropertyName 'hooks' -NotePropertyValue ([PSCustomObject]@{}) -Force
    }

    # 기존 hook이 있으면 확인
    # PermissionRequest는 Notification과 중복되므로 기본 설치에서 제외한다.
    # 즉시 알림을 원하면 settings.bat에서 켤 수 있다.
    foreach ($ev in @('Notification','Stop')) {
        if ($settings.hooks.PSObject.Properties[$ev] -and -not $Force) {
            $existing = $settings.hooks.$ev
            $isOurs = $existing | Where-Object { $_.hooks | Where-Object { $_.command -like '*claude-notify.ps1*' } }
            if (-not $isOurs) {
                Write-Warn2 (T "기존 $ev hook이 있습니다:" "An existing $ev hook was found:")
                foreach ($h in $existing) {
                    foreach ($c in $h.hooks) { Write-Host "       $($c.command)" -ForegroundColor DarkYellow }
                }
                $ans = Read-Host (T '  덮어쓸까요? (y/N)' '  Overwrite? (y/N)')
                if ($ans -notmatch '^[yY]') {
                    Write-Warn2 (T "$ev hook을 건너뜁니다." "Skipping $ev hook.")
                    continue
                }
            }
        }
        $cmd = if ($ev -eq 'Notification') { $cmdNotify } else { $cmdStop }
        $entry = [PSCustomObject]@{
            matcher = ''
            hooks   = @([PSCustomObject]@{ type = 'command'; command = $cmd })
        }
        $settings.hooks | Add-Member -NotePropertyName $ev -NotePropertyValue @($entry) -Force
        Write-Ok (T "$ev hook 등록" "Registered $ev hook")
    }

    # 저장: Claude Code는 BOM 없는 UTF-8 JSON을 기대한다
    try {
        $json = $settings | ConvertTo-Json -Depth 20
        [System.IO.File]::WriteAllText($SettingsPath, $json, [System.Text.UTF8Encoding]::new($false))
        # 검증
        $null = Get-Content $SettingsPath -Raw -Encoding UTF8 | ConvertFrom-Json
        Write-Ok (T 'settings.json 저장 및 검증 완료' 'settings.json saved and verified')
    } catch {
        Write-Err2 ((T '설정 저장 실패: ' 'Failed to save settings: ') + $_.Exception.Message)
        if ($bak) { Copy-Item $bak $SettingsPath -Force; Write-Warn2 (T '백업본으로 복구했습니다.' 'Restored from backup.') }
        return 1
    }

    # --- 5. 동작 테스트 ---
    Write-Head (T '[5/5] 동작 테스트' '[5/5] Test')
    try {
        & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $NotifyScript `
            -Message (T '설치가 완료되었습니다.' 'Installation complete.') -Hero $DoneImage 2>&1 | Out-Null
        if ($LASTEXITCODE -eq 0) {
            Write-Ok (T '테스트 알림 전송 (화면을 확인하세요)' 'Test notification sent (check your screen)')
        } else {
            Write-Warn2 ((T '테스트 알림 종료 코드: ' 'Test notification exit code: ') + $LASTEXITCODE)
        }
    } catch {
        Write-Warn2 ((T '테스트 실행 실패: ' 'Test failed: ') + $_.Exception.Message)
    }

    # --- 안내 ---
    Write-Host ''
    Write-Host '========================================' -ForegroundColor Green
    Write-Host (T '  설치 완료' '  Installation complete') -ForegroundColor Green
    Write-Host '========================================' -ForegroundColor Green
    Write-Host ''
    Write-Host (T '  Notification  확인이 필요할 때  (Clawd + 물음표)' '  Notification  when Claude needs you  (Clawd + question mark)') -ForegroundColor White
    Write-Host (T '  Stop          작업이 끝났을 때  (Clawd 만세 + 체크)' '  Stop          when a task is done    (Clawd cheering + check)') -ForegroundColor White
    Write-Host ''
    Write-Host (T '  실행 중인 Claude Code에 몇 초 안에 자동 반영됩니다.' '  Running Claude Code sessions pick this up within a few seconds.') -ForegroundColor Yellow
    Write-Host (T '  알림이 뜨지 않으면 Claude Code를 재시작하세요.' '  If notifications do not appear, restart Claude Code.') -ForegroundColor DarkYellow
    Write-Host ''
    Write-Host (T '  참고: Notification은 터미널을 보고 있으면 발생하지 않으며,' '  Note: Notification does not fire while you are looking at the terminal.') -ForegroundColor DarkGray
    Write-Host (T '        승인 대기는 약 6초, 유휴 알림은 약 60초 후에 발화합니다.' '        Permission prompts fire after ~6s, idle prompts after ~60s.') -ForegroundColor DarkGray
    Write-Host ''
    Write-Host (T '  설정 변경: settings.bat 을 실행하세요.' '  Settings : run settings.bat') -ForegroundColor DarkGray
    Write-Host (T '  제거     : uninstall.bat 을 실행하세요.' '  Uninstall: run uninstall.bat') -ForegroundColor DarkGray
    Write-Host ''
    return 0
}

# ---------------------------------------------------------------- 진입점
try {
    if ($Uninstall) { $code = Invoke-Uninstall }
    else            { $code = Invoke-Install }
} catch {
    Write-Err2 ((T '예기치 못한 오류: ' 'Unexpected error: ') + $_.Exception.Message)
    Write-Host $_.ScriptStackTrace -ForegroundColor DarkGray
    $code = 1
}

if ($Host.Name -eq 'ConsoleHost' -and -not $env:CLAWD_NONINTERACTIVE) {
    Write-Host (T '아무 키나 누르면 닫힙니다...' 'Press any key to close...') -ForegroundColor DarkGray
    $null = $Host.UI.RawUI.ReadKey('NoEcho,IncludeKeyDown')
}
exit $code
